<script setup>defineProps({model:{type:Object,required:true},handlers:{type:Object,required:true}});</script>
<template><template v-for="group in model.groups" :key="group.id"><div class="side-group">{{ group.label }}</div><div v-for="node in group.nodes" :key="node.id" :class="['side-item',{sel:node.selected}]" :data-node-id="node.id" role="button" tabindex="0" @click="handlers.select(node.id)" @keydown.enter.prevent="handlers.select(node.id)" @keydown.space.prevent="handlers.select(node.id)"><span class="side-dot" :style="{background:node.color}"></span><div style="min-width:0;flex:1"><div class="si-t">{{ node.title }}</div><div class="si-d">{{ node.count }}</div></div></div></template></template>
